vector<int> bfs(vector<vector<int>>& adj, int src) {
    int n = adj.size();
    vector<int> dist(n, -1);
    queue<int> q;
    dist[src] = 0; q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u])
            if (dist[v] == -1) {            // first visit = shortest
                dist[v] = dist[u] + 1;
                q.push(v);
            }
    }
    return dist;
}

from collections import deque
def bfs(adj, src):
    dist = {src: 0}
    q = deque([src])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)
    return dist

class Solution {
public:
    int numIslands(vector<vector<char>>& g) {
        int R = g.size(), C = g[0].size(), count = 0;
        int dx[] = {0,0,1,-1}, dy[] = {1,-1,0,0};
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++)
                if (g[i][j] == '1') {
                    count++;
                    queue<pair<int,int>> q; q.push({i, j}); g[i][j] = '0';
                    while (!q.empty()) {
                        auto [r, c] = q.front(); q.pop();
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dx[d], nc = c + dy[d];
                            if (nr >= 0 && nc >= 0 && nr < R && nc < C && g[nr][nc] == '1') {
                                g[nr][nc] = '0'; q.push({nr, nc});
                            }
                        }
                    }
                }
        return count;
    }
};

from collections import deque
class Solution:
    def numIslands(self, g: list[list[str]]) -> int:
        R, C, count = len(g), len(g[0]), 0
        for i in range(R):
            for j in range(C):
                if g[i][j] == '1':
                    count += 1
                    q = deque([(i, j)]); g[i][j] = '0'
                    while q:
                        r, c = q.popleft()
                        for nr, nc in ((r,c+1),(r,c-1),(r+1,c),(r-1,c)):
                            if 0 <= nr < R and 0 <= nc < C and g[nr][nc] == '1':
                                g[nr][nc] = '0'; q.append((nr, nc))
        return count

class Solution {
public:
    int orangesRotting(vector<vector<int>>& g) {
        int R = g.size(), C = g[0].size(), fresh = 0, minutes = 0;
        queue<pair<int,int>> q;
        for (int i = 0; i < R; i++) for (int j = 0; j < C; j++) {
            if (g[i][j] == 2) q.push({i, j});
            else if (g[i][j] == 1) fresh++;
        }
        int dx[] = {0,0,1,-1}, dy[] = {1,-1,0,0};
        while (!q.empty() && fresh) {
            int sz = q.size(); minutes++;
            while (sz--) {
                auto [r, c] = q.front(); q.pop();
                for (int d = 0; d < 4; d++) {
                    int nr = r + dx[d], nc = c + dy[d];
                    if (nr >= 0 && nc >= 0 && nr < R && nc < C && g[nr][nc] == 1) {
                        g[nr][nc] = 2; fresh--; q.push({nr, nc});
                    }
                }
            }
        }
        return fresh ? -1 : minutes;
    }
};

from collections import deque
class Solution:
    def orangesRotting(self, g: list[list[int]]) -> int:
        R, C = len(g), len(g[0])
        q, fresh = deque(), 0
        for i in range(R):
            for j in range(C):
                if g[i][j] == 2: q.append((i, j))
                elif g[i][j] == 1: fresh += 1
        minutes = 0
        while q and fresh:
            minutes += 1
            for _ in range(len(q)):
                r, c = q.popleft()
                for nr, nc in ((r,c+1),(r,c-1),(r+1,c),(r-1,c)):
                    if 0 <= nr < R and 0 <= nc < C and g[nr][nc] == 1:
                        g[nr][nc] = 2; fresh -= 1; q.append((nr, nc))
        return -1 if fresh else minutes

class Solution {
public:
    int ladderLength(string begin, string end, vector<string>& wordList) {
        unordered_set<string> dict(wordList.begin(), wordList.end());
        if (!dict.count(end)) return 0;
        queue<string> q; q.push(begin);
        int steps = 1;
        while (!q.empty()) {
            int sz = q.size();
            while (sz--) {
                string w = q.front(); q.pop();
                if (w == end) return steps;
                for (int i = 0; i < (int)w.size(); i++) {
                    char old = w[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        w[i] = c;
                        if (dict.count(w)) { dict.erase(w); q.push(w); }
                    }
                    w[i] = old;
                }
            }
            steps++;
        }
        return 0;
    }
};

from collections import deque
class Solution:
    def ladderLength(self, begin, end, wordList):
        dict_ = set(wordList)
        if end not in dict_:
            return 0
        q = deque([begin])
        steps = 1
        while q:
            for _ in range(len(q)):
                w = q.popleft()
                if w == end:
                    return steps
                for i in range(len(w)):
                    for c in 'abcdefghijklmnopqrstuvwxyz':
                        nxt = w[:i] + c + w[i+1:]
                        if nxt in dict_:
                            dict_.remove(nxt); q.append(nxt)
            steps += 1
        return 0

class Solution {
public:
    vector<vector<int>> updateMatrix(vector<vector<int>>& mat) {
        int R = mat.size(), C = mat[0].size();
        vector<vector<int>> dist(R, vector<int>(C, -1));
        queue<pair<int,int>> q;
        for (int i = 0; i < R; i++) for (int j = 0; j < C; j++)
            if (mat[i][j] == 0) { dist[i][j] = 0; q.push({i, j}); }
        int dx[] = {0,0,1,-1}, dy[] = {1,-1,0,0};
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (int d = 0; d < 4; d++) {
                int nr = r + dx[d], nc = c + dy[d];
                if (nr >= 0 && nc >= 0 && nr < R && nc < C && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1; q.push({nr, nc});
                }
            }
        }
        return dist;
    }
};

from collections import deque
class Solution:
    def updateMatrix(self, mat):
        R, C = len(mat), len(mat[0])
        dist = [[-1] * C for _ in range(R)]
        q = deque()
        for i in range(R):
            for j in range(C):
                if mat[i][j] == 0:
                    dist[i][j] = 0; q.append((i, j))
        while q:
            r, c = q.popleft()
            for nr, nc in ((r,c+1),(r,c-1),(r+1,c),(r-1,c)):
                if 0 <= nr < R and 0 <= nc < C and dist[nr][nc] == -1:
                    dist[nr][nc] = dist[r][c] + 1; q.append((nr, nc))
        return dist

class Solution {
public:
    int shortestPathBinaryMatrix(vector<vector<int>>& g) {
        int n = g.size();
        if (g[0][0] || g[n-1][n-1]) return -1;
        queue<pair<int,int>> q; q.push({0, 0}); g[0][0] = 1;
        int dist = 1;
        while (!q.empty()) {
            int sz = q.size();
            while (sz--) {
                auto [r, c] = q.front(); q.pop();
                if (r == n - 1 && c == n - 1) return dist;
                for (int dr = -1; dr <= 1; dr++)
                    for (int dc = -1; dc <= 1; dc++) {
                        int nr = r + dr, nc = c + dc;
                        if (nr >= 0 && nc >= 0 && nr < n && nc < n && g[nr][nc] == 0) {
                            g[nr][nc] = 1; q.push({nr, nc});
                        }
                    }
            }
            dist++;
        }
        return -1;
    }
};

from collections import deque
class Solution:
    def shortestPathBinaryMatrix(self, g):
        n = len(g)
        if g[0][0] or g[n-1][n-1]:
            return -1
        q = deque([(0, 0)]); g[0][0] = 1
        dist = 1
        while q:
            for _ in range(len(q)):
                r, c = q.popleft()
                if r == n - 1 and c == n - 1:
                    return dist
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and g[nr][nc] == 0:
                            g[nr][nc] = 1; q.append((nr, nc))
            dist += 1
        return -1
